import React from 'react';
import { useTheme } from '../context/ThemeContext';

const notifications = [
  { id: 1, type: 'star', message: 'You earned 1 star for daily login!', time: '2 mins ago', read: false },
  { id: 2, type: 'like', message: 'Rahul K liked your post on The Canvas', time: '1 hour ago', read: false },
  { id: 3, type: 'comment', message: 'Priya S commented on your post', time: '3 hours ago', read: true },
  { id: 4, type: 'star', message: 'You earned 5 stars for reaching 10 likes!', time: '1 day ago', read: true },
  { id: 5, type: 'update', message: 'New feature: Star Galaxy Leaderboard is live!', time: '2 days ago', read: true },
];

const icons = { star: '⭐', like: '❤️', comment: '💬', update: '🆕' };

export default function NotificationsModal({ onClose }) {
  const { t } = useTheme();

  return (
    <div style={{
      position: 'fixed', top: '56px', right: '16px', zIndex: 1001,
      width: '360px', background: t.bgCard,
      border: `1px solid ${t.border}`, borderRadius: '12px',
      boxShadow: t.shadowLg, overflow: 'hidden'
    }}>
      {/* Header */}
      <div style={{
        padding: '14px 16px', borderBottom: `1px solid ${t.border}`,
        display: 'flex', justifyContent: 'space-between', alignItems: 'center'
      }}>
        <h3 style={{ color: t.textPrimary, fontSize: '14px', fontWeight: 600, margin: 0 }}>
          Notifications
        </h3>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <span style={{ color: t.accent, fontSize: '12px', cursor: 'pointer' }}>Mark all read</span>
          <button onClick={onClose} style={{
            background: t.bgTertiary, border: `1px solid ${t.border}`,
            borderRadius: '4px', width: '22px', height: '22px',
            color: t.textSecondary, cursor: 'pointer', fontSize: '12px'
          }}>×</button>
        </div>
      </div>

      {/* Notifications List */}
      <div style={{ maxHeight: '360px', overflowY: 'auto' }}>
        {notifications.map(notif => (
          <div key={notif.id} style={{
            padding: '12px 16px', borderBottom: `1px solid ${t.border}`,
            display: 'flex', gap: '10px', alignItems: 'flex-start',
            background: notif.read ? 'transparent' : t.accentSubtle,
            cursor: 'pointer', transition: 'background 0.15s'
          }}
            onMouseEnter={e => e.currentTarget.style.background = t.bgHover}
            onMouseLeave={e => e.currentTarget.style.background = notif.read ? 'transparent' : t.accentSubtle}
          >
            <span style={{ fontSize: '18px', marginTop: '2px' }}>{icons[notif.type]}</span>
            <div style={{ flex: 1 }}>
              <p style={{ color: t.textPrimary, fontSize: '13px', margin: '0 0 3px', lineHeight: '1.4' }}>
                {notif.message}
              </p>
              <p style={{ color: t.textMuted, fontSize: '11px', margin: 0 }}>{notif.time}</p>
            </div>
            {!notif.read && (
              <div style={{
                width: '8px', height: '8px', borderRadius: '50%',
                background: t.accent, flexShrink: 0, marginTop: '4px'
              }} />
            )}
          </div>
        ))}
      </div>

      <div style={{ padding: '10px 16px', borderTop: `1px solid ${t.border}`, textAlign: 'center' }}>
        <span style={{ color: t.accent, fontSize: '13px', cursor: 'pointer' }}>View all notifications</span>
      </div>
    </div>
  );
}
